23\uD83E\uDD23\uD83E\uDD23\uD83E\uDD23\uD83E\uDD23\uD83E\uDD23\uD83E\uDD23\uD83E\uDD23\uD83E\uDD23\uD83E\uDD23\uD83E\uDD23\uD83E\uDD23\uD83E\uDD23\uD83E\uDD23\uD83E\uDD23\uD83E\uDD23\uD83E\uDD23\uD83E\uDD23\uD83E\uDD23\uD83E\uDD23\uD83E\uDD23\uD83E\uDD23\uD83E\uDD23\uD83E\uDD23\uD83E\uDD23\uD83E\uDD23\uD83E\uDD23\uD83E\uDD23\uD83E\uDD23\uD83E\uDD23\uD83E\uDD23\uD83E\uDD23\uD83E\uDD23\uD83E\uDD23\uD83E\uDD23\uD83E\uDD23\uD83E\uDD23\uD83E\uDD23\uD83E\uDD23\uD83E\uDD23\uD83E\uDD23\uD83E\uDD23\uD83E\uDD23\uD83E\uDD23\uD83E\uDD23\uD83E\uDD23\uD83E\uDD23\uD83E\uDD23\uD83E\uDD23\uD83E\uDD23\uD83E\uDD23\uD83E\uDD23\uD83E\uDD23\uD83E\uDD23\uD83E\uDD23\uD83E\uDD23\uD83E\uDD23\uD83E\uDD23\uD83E\uDD23\uD83E\uDD23\uD83E\uDD23\uD83E\uDD23\uD83E\uDD23\uD83E\uDD23\uD83E\uDD23\uD83E\uDD23\uD83E\uDD23\uD83E\uDD23\uD83E\uDD23\uD83E\uDD23\uD83E\uDD23\uD83E\uDD23\uD83E\uDD23\uD83E\uDD23\uD83E\uDD23\uD83E\uDD23\uD83E\uDD23\uD83E\uDD23\uD83E\uDD23"
            )
        }
    }

    val listState = rememberLazyListState()

    Scaffold(
        topBar = {
            Box(
                modifier = Modifier.Companion
                    .fillMaxWidth()
                    .windowInsetsPadding(
                        WindowInsets.Companion.safeDrawing.only(
                            WindowInsetsSides.Companion.Top + WindowInsetsSides.Companion.Horizontal
                        )
                    )
                    .padding(12.dp)
            ) {
                Text("Scroll Mode - eventflag")
            }
        },
        bottomBar = {
            Box(
                Modifier.Companion
                    .fillMaxWidth()
                    .windowInsetsPadding(
                        WindowInsets.Companion.safeDrawing.only(
                            WindowInsetsSides.Companion.Bottom + WindowInsetsSides.Companion.Horizontal
                        )
                    )
            ) {
                InputBar { text ->
                    messages.add(text)
                }
            }
        }
    ) { innerPadding ->
        class Ref<T>(var value: T)

        //▼AndroidViewでIME開閉動作開始/終了のイベントを捕まえる
        val maxInset = remember { Ref(0f) }
        val directionSign = remember { Ref(+1) }
        val isStart = remember { Ref(false) }
        val isScroll = remember { Ref(false) }
        val isEnd = remember { Ref(false) }
        val previousFraction = remember { Ref(0f) }
        val previousDistance = remember { Ref(0f) }
        var distance by remember { mutableFloatStateOf(0f) }
        AndroidView(
            modifier = Modifier.Companion
                .fillMaxSize()
                .alpha(0f), // 完全透過（当たり判定なし）
            factory = { context ->
                View(context).apply {
                    ViewCompat.setWindowInsetsAnimationCallback(
                        this,
                        object: WindowInsetsAnimationCompat.Callback(
                            DISPATCH_MODE_CONTINUE_ON_SUBTREE
                        ) {
                            override fun onPrepare(
                                animation: WindowInsetsAnimationCompat
                            ) {
                                super.onPrepare(animation)

                                val isVisibleIme = ViewCompat.getRootWindowInsets(this@apply)
                                    ?.isVisible(animation.typeMask and WindowInsetsCompat.Type.ime())
                                if (isVisibleIme == false) {
                                    directionSign.value = +1
                                } else {
                                    directionSign.value = -1
                                }
                                Log.d("onPrepare", "isVisibleIme=${isVisibleIme}")
                            }

                            override fun onStart(
                                animation: WindowInsetsAnimationCompat,
                                bounds: WindowInsetsAnimationCompat.BoundsCompat
                            ): WindowInsetsAnimationCompat.BoundsCompat {
                                if (animation.typeMask and WindowInsetsCompat.Type.ime() != 0) {
                                    maxInset.value =
                                        (bounds.upperBound.bottom - bounds.lowerBound.bottom).toFloat()
                                    distance = maxInset.value * animation.fraction
                                    isStart.value = true
                                    Log.d("onStart", "distance=${distance}")
                                }
                                return bounds
                            }

                            override fun onProgress(
                                insets: WindowInsetsCompat,
                                runningAnimations: List<WindowInsetsAnimationCompat>
                            ): WindowInsetsCompat {
                                val imeAnimation = runningAnimations.find {
                                    it.typeMask and WindowInsetsCompat.Type.ime() != 0
                                }
                                if (imeAnimation != null) {
                                    val fraction = imeAnimation.interpolatedFraction
                                    val delta = fraction - previousFraction.value
                                    if ((delta > 0.02f) or (fraction == 1.0f)) {
                                        isScroll.value = true
                                        distance =
                                            maxInset.value * fraction
                                        previousFraction.value = fraction
                                        Log.d("onProgress", "distance=${distance}")
                                    }
                                }
                                return insets
                            }

                            // ▼onProgress()直後に呼ばれる（LaunchedEffectよりも早く）
                            override fun onEnd(
                                animation: WindowInsetsAnimationCompat
                            ){
                                if (animation.typeMask and WindowInsetsCompat.Type.ime() != 0) {
                                    isEnd.value = true
                                    distance = maxInset.value * animation.fraction
                                    Log.d("onEnd", "distance=${distance}")
                                }
                            }
                        }
                    )
                }
            }
        )

        //▼メッセージが追加/削除されたとき、最下部へ移動
        LaunchedEffect(messages.size) {
            if (messages.isNotEmpty()) {
                // 1. 最後のアイテムまで一度ジャンプし、Composeにアイテムを描画（レイアウト生成）させる
                listState.scrollToItem(messages.lastIndex)

                // 2. 描画が完了し、画面内に最後のアイテムが実際に表示されるまで待機
                snapshotFlow { listState.layoutInfo }
                    .first { info ->
                        info.visibleItemsInfo.any { it.index == messages.lastIndex }
                    }

                // 3. 画面サイズ基準でどれだけアイテムがはみ出るかの差分を計算
                // 3-1. レイアウト情報取得
                val layoutInfo = listState.layoutInfo
                // 3-2. 最後のアイテムを取得
                val lastItem = layoutInfo.visibleItemsInfo.last()
                // 3-3. アイテムの高さ - リストの表示高さ
                val offset = lastItem.size - layoutInfo.viewportSize.height

                // 4. アイテムの高さが画面に収まらない場合のみ、下端が切れないように再ジャンプで微調整
                if (offset > 0) {
                    listState.scrollToItem(messages.lastIndex, offset)
                }
            }
        }

        //▼IMEに追従してLazyColumnのスクロール位置補正
        LaunchedEffect(distance) {
            if (isStart.value == true) {
                previousDistance.value = distance
                isStart.value = false
                isScroll.value = false
                previousFraction.value = 0f
                Log.d("isStart", "previousDistance=${previousDistance.value}")
                isEnd.value = false
            }
            if (isScroll.value == true) {
                val tmp =
                    listState.scrollBy(directionSign.value * (distance - previousDistance.value))
                Log.d(
                    "isScroll",
                    "tmp=${tmp}, previousDistance=${previousDistance.value}, distance=${distance}"
                )
                previousDistance.value += (directionSign.value * tmp)
                isScroll.value = false
            }
            if (isEnd.value == true) {
                val tmp = listState.scrollBy(directionSign.value * (distance - previousDistance.value))
                Log.d("isEnd", "tmp=${tmp}, previousDistance=${previousDistance.value}, distance=${distance}")
                previousDistance.value += (directionSign.value * tmp)
                isEnd.value = false
            }
        }

        LazyColumn(
            modifier = Modifier.Companion
                .fillMaxSize()
                .padding(innerPadding),
            state = listState,
            verticalArrangement = Arrangement.Bottom // 下貼り付き
        ) {
            items(messages) { msg ->
                MessageBubble(text = msg)
            }
        }
    }
}